mapper.select:
SELECT r.id, IF(r.is_anonymous = 1, NULL, r.user_id) AS user_id, r.order_id, r.order_item_id, r.product_id, r.sku_id, r.rating, r.content, r.images, r.is_anonymous, r.status, r.created_at, IF(r.is_anonymous = 1, '匿***', u.nickname) AS nickname, IF(r.is_anonymous = 1, NULL, u.avatar) AS avatar FROM t_review r LEFT JOIN t_user u ON u.id = r.user_id WHERE r.product_id = #{productId} AND r.status = 1
AND r.rating = #{rating}
ORDER BY r.id DESC
